def solve(n, edges, s, t):
    from collections import defaultdict, deque

    if s == t:
        return 0

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n

    queue = deque()
    queue.append(s)

    while queue:
        u = queue.popleft()
        visited[u] = True

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    queue.append(v)

    return dist[t] if dist[t] != float('inf') else -1

def solve(n, edges, s, t):
    from collections import defaultdict

    if s == t:
        return 0

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0

    for _ in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    return dist[t] if dist[t] != float('inf') else -1

